using System;
using System.IO;
using System.Linq;
using UnityEngine;
using AnimalArchive.Voyage;
public static class VoyageV8Verification {
 static int checks;static void Check(bool b,string name){checks++;if(!b)throw new Exception("V8 FAILED: "+name);}
 static VoyageModel Rich(VoyageConfig c,long boarded=0){return new VoyageModel(c,new VoyageState{total=200000,available=200000,boarded=boarded,nextId=boarded,paidPrefix=boarded});}
 public static void Run(){checks=0;var cfg=JsonUtility.FromJson<VoyageConfig>(File.ReadAllText("Assets/Resources/Voyage/config.json"));var m=Rich(cfg,100);long before=m.state.spent;Check(!m.SetAuto(true,4)&&!m.Buy(0,true),"auto investment disabled");for(int i=0;i<500;i++)m.Tick(.1f);Check(m.state.spent==before,"no background purchases");Check(m.GrowthDot,"affordable growth dot");for(int k=0;k<4;k++)while(m.Buy(k)){}Check(!m.GrowthDot,"dot cleared only when all maxed");Check(m.CanHire&&m.StaffDot&&m.Hire(),"shepherd hire");Check(m.Expand()&&m.state.area==1,"farm expansion");Check(m.CanHire&&m.Hire()&&m.state.workers.Count==3,"gardener hire after land");Check(m.Expand()&&m.state.area==2,"second functional region");Check(m.LandTarget(-.65f,.7f).x<-.6f,"expanded area traversable");m.Plant(0,0);m.Plant(1,2);Check(m.state.plots[0].crop==0&&m.state.plots[1].crop==2,"different crops");float unbuffed=m.Weight(4);for(int i=0;i<7;i++)m.Water(1);Check(m.Harvest(1)&&m.Weight(4)>unbuffed*3,"moonflower actually changes owl composition");Check(m.state.spent>before,"only explicit spending");
  bool rest=false,resume=false;for(int i=0;i<800;i++){m.Tick(.1f);rest|=m.events.Any(e=>e.StartsWith("rest:"));resume|=m.events.Any(e=>e.StartsWith("work:"));m.events.Clear();m.arrivals.Clear();}Check(rest&&resume,"autonomous work/rest/resume");Check(m.state.workers[2].x<0,"gardener physically visits plots");Check(m.state.plots.Any(p=>p.harvests>0),"gardener harvest loop");
  var control=Rich(cfg,100);control.Hire();control.state.workers[0].rest=5;Check(control.Tap(.4f,.65f)&&control.state.workers[0].rest==0,"manual main worker wakes from rest");Check(!control.CommandWorker(1,float.NaN,.6f),"reject invalid manual coordinates");var helper=control.state.workers[1];helper.x=.1f;helper.y=.65f;helper.rest=5;Check(control.CommandWorker(1,.7f,.7f)&&helper.rest==0,"manual employee wakes and accepts destination");Check(!control.CommandWorker(1,.7f,.7f),"manual employee command rate bounded");Check(helper.x==.1f&&helper.tx==.7f,"employee does not teleport");control.Tick(.1f);Check(helper.x>.1f&&helper.x<.2f,"employee walks after command");Check(helper.manual>0&&helper.cooldown>0,"manual employee emits local guidance with cooldown");
  var off=Rich(cfg,100);off.BeginBackground(1000);long total=off.state.total;int active=off.state.active.Count;long reward=off.ApplyAway(1060);Check(reward>0&&off.state.total==total+reward,"offline positive exact credit");Check(off.state.active.Count==active&&off.state.boarded==100,"offline no animal simulation");Check(off.ApplyAway(1060)==0&&off.ApplyAway(900)==0,"offline replay and clock rollback rejected");off.BeginBackground(2000);Check(off.ApplyAway(100000)>0&&off.state.awaySeconds==600,"open background time cap");Check(VoyageModel.Validate(cfg,off.state,out _),"offline ledger");string encoded=VoyageSave.Encode(off.state);Check(VoyageSave.Decode(cfg,encoded)!=null,"V8 save reload");
  var fight=Rich(cfg,650);fight.state.crisis=2;fight.Tick(.1f);Check(fight.state.demon==1,"progress warning trigger");for(int i=0;i<61;i++)fight.Tick(.1f);Check(fight.DemonActive,"timed warning enters demon");long earned=fight.state.total;for(int i=0;i<200&&fight.DemonActive;i++){fight.Pray(.1f);fight.Tick(.1f);}Check(fight.state.demon==3&&fight.state.demonTime<20,"active prayer resolves quickly");Check(fight.state.total>=earned,"crisis never confiscates banked income");Check(VoyageModel.Validate(cfg,fight.state,out var why),"prayer ledger "+why);
  var afk=Rich(cfg,650);long bankedBeforeAttack=afk.state.total;afk.state.crisis=2;for(int i=0;i<720;i++){afk.Tick(.1f);afk.events.Clear();afk.arrivals.Clear();}Check(afk.state.demon==3,"unattended crisis naturally recovers");Check(afk.state.total>=bankedBeforeAttack,"unattended boss never confiscates banked contribution");Check(VoyageModel.Validate(cfg,afk.state,out why),"loss ledger "+why);Check(!afk.Pray(.1f),"prayer unavailable outside crisis");
  var fresh=new VoyageModel(cfg);bool wandering=false;for(int i=0;i<500;i++){fresh.Tick(.1f);wandering|=fresh.state.active.Any(p=>p.roamBlend>.5f);fresh.events.Clear();fresh.arrivals.Clear();}Check(wandering,"animals visibly loiter");Check(VoyageModel.Response(1)>VoyageModel.Response(0),"different guidance response");fresh.state.discovered=3;fresh.state.seenSpecies=1;Check(fresh.NewCodex,"unread species badge");fresh.state.seenSpecies=3;Check(!fresh.NewCodex,"only read species clears codex badge");
  var report=new System.Text.StringBuilder("V8 actual C# model checks\n");foreach(bool activePlay in new[]{false,true}){var sim=new VoyageModel(cfg);float nextBuy=0;while(!sim.state.completed&&sim.state.elapsed<900){sim.Tick(.1f);if(activePlay){var target=sim.state.active.FirstOrDefault(p=>p.age>=0&&!p.admitted);if(target!=null&&((int)(sim.state.elapsed*10))%3==0){Vector2 at=VoyageModel.Position(target);sim.Tap(at.x,at.y);}sim.Pray(.1f);if(sim.CrisisActive)sim.Shelter();if(sim.state.guideCooldown<=0)sim.CallGuide();}if(sim.state.elapsed>=nextBuy){nextBuy=sim.state.elapsed+3;if(sim.CanHire)sim.Hire();if(sim.CanExpand)sim.Expand();for(int k=0;k<sim.state.area;k++){if(sim.state.plots[k].crop<0)sim.Plant(k,k==0?0:2);if(activePlay)sim.Harvest(k);}if(sim.TwilightReady)sim.LightLantern();int pick=-1;long cost=long.MaxValue;for(int i=0;i<4;i++)if(sim.CanBuy(i)&&sim.Cost(i)<cost){cost=sim.Cost(i);pick=i;}if(pick>=0)sim.Buy(pick);if(sim.CanSail)sim.RequestSail();}sim.events.Clear();sim.arrivals.Clear();}Check(sim.state.completed,"full economic loop completion "+activePlay);Check(sim.state.workers.Count==3&&sim.state.area==2,"all systems reached "+activePlay);Check(sim.state.active.Count==0,"all boarding drained "+activePlay);Check(VoyageModel.Validate(cfg,sim.state,out why),"completed ledger "+why);report.AppendLine((activePlay?"active":"idle + periodic purchases")+": "+sim.state.endTime.ToString("F1")+" seconds, "+sim.state.endBoarded+" boarded, "+sim.state.lost+" lost, "+sim.state.endDiscovered+" species");}
  report.AppendLine("PASS "+checks+" V8 checks");Directory.CreateDirectory("../Evidence/V102");File.WriteAllText("../Evidence/V102/economy-verification.txt",report.ToString());Debug.Log(report.ToString());
 }
}

